function fitQuote(){const quote=$('quote'),host=quote.parentElement;const text=quoteText(active);quote.classList.toggle('long',text.length>155);quote.style.fontSize='';if(settings.listenFirst&&directSpeech(active))return;let f=text.length>220?18:text.length>150?20:26;quote.style.fontSize=f+'px';for(;f>=11&&(quote.scrollHeight>host.clientHeight-2||quote.scrollWidth>host.clientWidth-2);f--){quote.style.fontSize=f+'px'}if(quote.scrollHeight>host.clientHeight+2){document.querySelector('.stage').classList.add('extra-long')}else{document.querySelector('.stage').classList.remove('extra-long')}}
