 function confirm(){if(!selected.size||answered||placements.length!==idx)return;const chosen=[...selected].sort(),actual=sortLabels(sortOpts[idx]).slice().sort();const ok=chosen.length===actual.length&&chosen.every((k,i)=>k===actual[i]);const partial=!ok&&chosen.some(k=>actual.includes(k));placements.push({item:sortOpts[idx],chosen,ok,partial});card.classList.add('popped');setTimeout(()=>drawSort(q),120)}
 for(const k of available){const b=el('button','bin');b.dataset.bin=k;b.type='button';b.setAttribute('aria-pressed','false');b.append(el('span','bi',k==='anxiety'?'♡':k==='avoidance'?'◇':k==='secure'?'✿':'?'),el('span','',BIN[k]));b.addEventListener('click',()=>toggle(k));buttons.push(b);bins.appendChild(b)}
