 card.addEventListener('pointermove',e=>{if(!dragState)return;if(Math.hypot(e.clientX-dragState.x,e.clientY-dragState.y)>14)dragState.drag=true;if(dragState.drag){card.classList.add('dragging');const hit=document.elementFromPoint(e.clientX,e.clientY)?.closest?.('[data-bin]');buttons.forEach(b=>b.classList.toggle('hover',b===hit))}});
